import React, { useEffect, useMemo, useRef } from "react";
import styled from "styled-components";
import { motion } from "framer-motion";
import { Link, useNavigate } from "react-router-dom";
import { ArrowLeft, BookOpen, List } from "lucide-react";
import { animate, stagger, text, createScope, type Scope } from "animejs";
import JournalBody from "../components/growth/JournalBody";
import {
  JOURNAL_TRACK_LABELS,
  ML_JOURNAL_POSTS,
  type JournalTrack,
  type MlJournalPost,
} from "../data/mlJournalPosts";
import MiniGameCard from "../components/growth/MiniGameCard";
import MiniGameRenderer from "../components/growth/MiniGameRegistry";

const TRACK_ORDER: JournalTrack[] = ["ml", "interaction", "build"];

const PageWrap = styled.div`
  min-height: 100vh;
  background: ${(props) => props.theme.colors.background};
  color: ${(props) => props.theme.colors.text};
  padding: 2rem 1.25rem 4rem;
`;

const Inner = styled.div`
  max-width: 780px;
  margin: 0 auto;
`;

const BackBar = styled.div`
  margin-bottom: 2rem;
`;

const BackBtn = styled(motion.button)`
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.55rem 1rem;
  border-radius: 12px;
  border: 1px solid ${(props) => props.theme.colors.border};
  background: ${(props) => props.theme.colors.surface};
  color: ${(props) => props.theme.colors.text};
  font-size: 0.92rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;

  &:hover {
    border-color: ${(props) => props.theme.colors.primary};
    color: ${(props) => props.theme.colors.primary};
  }
`;

const PageTitle = styled.h1`
  font-size: clamp(1.85rem, 4.5vw, 2.35rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.2;
  margin-bottom: 0.65rem;
  background: ${(props) => props.theme.colors.gradient};
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
`;

const PageLead = styled.p`
  color: ${(props) => props.theme.colors.textSecondary};
  font-size: 1.02rem;
  line-height: 1.7;
  margin-bottom: 1.25rem;
  max-width: 62ch;
`;

const Toc = styled.nav`
  margin-bottom: 2.5rem;
  padding: 1rem 1.1rem;
  border-radius: 12px;
  border: 1px solid ${(props) => props.theme.colors.border};
  background: ${(props) => props.theme.colors.surface};
`;

const TocHead = styled.div`
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: ${(props) => props.theme.colors.primary};
  margin-bottom: 0.85rem;
`;

const TocGroup = styled.div`
  &:not(:last-child) {
    margin-bottom: 0.85rem;
    padding-bottom: 0.85rem;
    border-bottom: 1px solid ${(props) => props.theme.colors.border};
  }
`;

const TocGroupLabel = styled.div`
  font-size: 0.8rem;
  font-weight: 700;
  color: ${(props) => props.theme.colors.text};
  margin-bottom: 0.35rem;
`;

const TocList = styled.ul`
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
`;

const TocLink = styled.a`
  font-size: 0.88rem;
  color: ${(props) => props.theme.colors.textSecondary};
  text-decoration: none;
  line-height: 1.45;

  &:hover {
    color: ${(props) => props.theme.colors.primary};
    text-decoration: underline;
  }
`;

const TrackHeader = styled.h2`
  font-size: 0.82rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: ${(props) => props.theme.colors.textMuted};
  margin: 0 0 1.5rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid ${(props) => props.theme.colors.border};
`;

const Article = styled(motion.article)`
  padding-bottom: 3.5rem;
  margin-bottom: 3rem;
  border-bottom: 1px solid ${(props) => props.theme.colors.border};

  &:last-child {
    border-bottom: none;
    margin-bottom: 0;
    padding-bottom: 0;
  }
`;

const ArticleMeta = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 0.75rem;
  margin-bottom: 0.65rem;
`;

const TrackBadge = styled.span`
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 0.22rem 0.55rem;
  border-radius: 6px;
  background: ${(props) => props.theme.colors.primary}18;
  color: ${(props) => props.theme.colors.primary};
`;

const TagRow = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
`;

const Tag = styled.span`
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  padding: 0.2rem 0.55rem;
  border-radius: 7px;
  background: ${(props) => props.theme.colors.surface};
  border: 1px solid ${(props) => props.theme.colors.border};
  color: ${(props) => props.theme.colors.textSecondary};
`;

const ArticleTitle = styled.h3`
  font-size: clamp(1.35rem, 3.2vw, 1.65rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 0.55rem;
  color: ${(props) => props.theme.colors.text};
`;

const ArticleSummary = styled.p`
  font-size: 0.94rem;
  line-height: 1.65;
  color: ${(props) => props.theme.colors.textSecondary};
  margin: 0 0 1.35rem;
  max-width: 58ch;
`;

const SectionBlock = styled.section`
  margin-bottom: 1.5rem;

  &:last-of-type {
    margin-bottom: 0;
  }
`;

const SectionTitle = styled.h4`
  font-size: 0.95rem;
  font-weight: 700;
  color: ${(props) => props.theme.colors.primary};
  margin-bottom: 0.5rem;
  letter-spacing: -0.01em;
`;

const ArticleLinks = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 0.75rem;
  margin: 1.25rem 0 0;
`;

const ArticleLink = styled.a`
  font-size: 0.84rem;
  font-weight: 600;
  color: ${(props) => props.theme.colors.primary};
  text-decoration: none;
  padding: 0.35rem 0.7rem;
  border-radius: 8px;
  border: 1px solid ${(props) => props.theme.colors.border};
  background: ${(props) => props.theme.colors.surface};

  &:hover {
    border-color: ${(props) => props.theme.colors.primary};
    text-decoration: underline;
  }
`;

const HomeSectionLink = styled(Link)`
  font-size: 0.84rem;
  font-weight: 600;
  color: ${(props) => props.theme.colors.primary};
  text-decoration: none;
  padding: 0.35rem 0.7rem;
  border-radius: 8px;
  border: 1px solid ${(props) => props.theme.colors.border};
  background: ${(props) => props.theme.colors.surface};

  &:hover {
    border-color: ${(props) => props.theme.colors.primary};
    text-decoration: underline;
  }
`;

function JournalArticle({
  post,
  index,
}: {
  post: MlJournalPost;
  index: number;
}) {
  return (
    <Article
      id={post.id}
      initial={{ opacity: 0, y: 24 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-40px" }}
      transition={{ duration: 0.5, delay: index * 0.04 }}
    >
      <ArticleMeta>
        <TrackBadge>{JOURNAL_TRACK_LABELS[post.track]}</TrackBadge>
        <TagRow>
          {post.tags.map((t) => (
            <Tag key={t}>{t}</Tag>
          ))}
        </TagRow>
      </ArticleMeta>
      <ArticleTitle>{post.title}</ArticleTitle>
      <ArticleSummary>{post.summary}</ArticleSummary>

      {post.links && post.links.length > 0 ? (
        <ArticleLinks>
          {post.links.map((link) =>
            link.label.includes("포트폴리오") ? (
              <HomeSectionLink
                key={link.href}
                to="/"
                state={{ scrollTo: "github-activity" }}
              >
                {link.label}
              </HomeSectionLink>
            ) : (
              <ArticleLink
                key={link.href}
                href={link.href}
                target="_blank"
                rel="noopener noreferrer"
              >
                {link.label}
              </ArticleLink>
            ),
          )}
        </ArticleLinks>
      ) : null}

      {post.sections.map((s) => (
        <SectionBlock key={s.heading}>
          <SectionTitle>{s.heading}</SectionTitle>
          <JournalBody text={s.body} />
        </SectionBlock>
      ))}

      {post.miniGame ? (
        <MiniGameCard meta={post.miniGame}>
          <MiniGameRenderer id={post.miniGame.id} />
        </MiniGameCard>
      ) : null}
    </Article>
  );
}

function GrowthJournalPage() {
  const navigate = useNavigate();
  const rootRef = useRef<HTMLDivElement | null>(null);
  const titleRef = useRef<HTMLHeadingElement | null>(null);

  const postsByTrack = useMemo(() => {
    const map = new Map<JournalTrack, MlJournalPost[]>();
    for (const t of TRACK_ORDER) map.set(t, []);
    for (const post of ML_JOURNAL_POSTS) {
      map.get(post.track)!.push(post);
    }
    return map;
  }, []);

  useEffect(() => {
    if (!rootRef.current) return;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduced || !titleRef.current) return;

    let scope: Scope | null = null;
    scope = createScope({ root: rootRef.current }).add((self) => {
      const splitter = text.splitText(titleRef.current!, {
        chars: { wrap: "clip" },
      });
      self?.register(splitter);
      animate(splitter.chars, {
        opacity: [0, 1],
        translateY: [18, 0],
        duration: 620,
        delay: stagger(24, { start: 80 }),
        ease: "outQuad",
      });
    });

    return () => {
      scope?.revert();
    };
  }, []);

  return (
    <PageWrap>
      <Inner ref={rootRef}>
        <BackBar>
          <BackBtn
            type="button"
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
            onClick={() => navigate("/")}
          >
            <ArrowLeft size={18} aria-hidden /> 메인으로
          </BackBtn>
        </BackBar>

        <motion.div
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.45 }}
        >
          <PageTitle ref={titleRef}>학습 노트</PageTitle>
          <PageLead>
            <BookOpen
              size={18}
              style={{
                verticalAlign: "-0.2em",
                marginRight: "0.35rem",
                opacity: 0.85,
              }}
              aria-hidden
            />
            실무와 별도로 손으로 검증한 기록입니다. 글마다{" "}
            <strong>해본 것 → 막혔던 점 → 정리한 것</strong> 순이고, ML 주제는
            아래 미니게임으로 이어집니다.
          </PageLead>

          <Toc aria-label="목차">
            <TocHead>
              <List size={14} aria-hidden /> 목차
            </TocHead>
            {TRACK_ORDER.map((track) => {
              const posts = postsByTrack.get(track) ?? [];
              if (posts.length === 0) return null;
              return (
                <TocGroup key={track}>
                  <TocGroupLabel>{JOURNAL_TRACK_LABELS[track]}</TocGroupLabel>
                  <TocList>
                    {posts.map((p) => (
                      <li key={p.id}>
                        <TocLink href={`#${p.id}`}>{p.title}</TocLink>
                      </li>
                    ))}
                  </TocList>
                </TocGroup>
              );
            })}
          </Toc>

          {TRACK_ORDER.map((track) => {
            const posts = postsByTrack.get(track) ?? [];
            if (posts.length === 0) return null;
            return (
              <section key={track} aria-labelledby={`track-${track}`}>
                <TrackHeader id={`track-${track}`}>
                  {JOURNAL_TRACK_LABELS[track]}
                </TrackHeader>
                {posts.map((post, i) => (
                  <JournalArticle key={post.id} post={post} index={i} />
                ))}
              </section>
            );
          })}
        </motion.div>
      </Inner>
    </PageWrap>
  );
}

export default GrowthJournalPage;
